\label{Definition 3} (see \cite{Z1} and Chapter 12 of \cite{Ge}) A family of vectors $l=\left\{l_{xy}\right\}_{\langle x, y) \in L}$ with $l_ {xy}=$ $\left\{l_{xy}(i): i \in \mathbb{N}\right\} \in(0, \infty)^{\mathbb{N}}$ is called the boundary law for the Hamiltonian (\ref{g1}) if

1) for each $\langle x, y\rangle \in L$ there exists a constant $c_{x y}>0$ such that the consistency equation
\begin{equation}\label{5}
l_{xy}(i)=c_{xy}  \prod_{z \in \partial x \backslash\{y\}} \sum_{j \in \mathbb{N}} \lambda_i a_{ij}\lambda_{j} l_{zx}(j)
\end{equation}
holds for any $i \in \mathbb{N}$, where $\partial x$ is the set of nearest neighbors of $x$.

2) The boundary law $l$ is said to be normalisable if and only if
\begin{equation}\label{6}
\sum_{i \in \mathbb{N}}\left(\prod_{z \in \partial x} \sum_{j \in \mathbb{N}}\lambda_i a_{ij}\lambda_{j} l_{zx} (j)\right)<\infty
\end{equation}
for all $x \in V$.

\label{tz} \cite{Z1}
For any Gibbsian specification $\gamma$ with associated family of transfer matrices $(Q_b)_{b \in L}$  we have
\begin{enumerate}
\item Each {\it normalisable} boundary law $(l_{xy})_{x,y}$ for $(Q_b)_{b \in L}$ defines a unique Gibbs measure $\mu$ (corresponding to $\gamma$)  via the equation given for any connected set $\Lambda \subset V$
\begin{equation}\label{BoundMC}
	\mu(\sigma_{\Lambda \cup \partial \Lambda}=\omega_{\Lambda \cup \partial \Lambda}) = (Z_\Lambda)^{-1} \prod_{y \in \partial \Lambda} l_{y y_\Lambda}(\omega(y)) \prod_{b \cap \Lambda \neq \emptyset} Q_b(\omega_b),
\end{equation}
where for any $y \in \partial \Lambda$, $y_\Lambda$ denotes the unique nearest-neighbor of $y$ in $\Lambda$.
\item Conversely, every Gibbs measure $\mu$ admits a representation of the form (\ref{BoundMC}) in terms of a {\it normalisable} boundary law (unique up to a constant positive factor).
\end{enumerate}
